<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
$socket=getenv('SOSECURITY_TEST_MYSQL_SOCKET');
if(!is_string($socket)||!preg_match('~\A/tmp/sosecurity-mysql-[A-Za-z0-9_-]+/mysql\.sock\z~D',$socket)||!is_file(dirname($socket).'/account-test-owner')||is_link(dirname($socket))){throw new RuntimeException('Owned MySQL required');}
$pdo=new PDO('mysql:unix_socket='.$socket.';dbname=sosecurity_test','sosecurity_test','integration-only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$created=[];$reader=new PDO('mysql:unix_socket='.$socket.';dbname=sosecurity_test','sosecurity_reader','integration-read-only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
try{
 $pdo->exec('CREATE TABLE sosecurity_fk_probe(id INT NOT NULL PRIMARY KEY) ENGINE=InnoDB');$created[]='sosecurity_fk_probe';
 $old=SoSecurity\Support\SqlSchema::foreignKeyChecks('mysql','sosecurity_fk_probe')[0];
 $outgoing='LOWER(TABLE_SCHEMA)=LOWER(DATABASE()) AND LOWER(TABLE_NAME)=:outgoing AND (@@lower_case_table_names<>0 OR (TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:outgoing_lookup AND BINARY TABLE_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=:outgoing_exact))';
 $incoming='LOWER(REFERENCED_TABLE_SCHEMA)=LOWER(DATABASE()) AND LOWER(REFERENCED_TABLE_NAME)=:incoming AND (@@lower_case_table_names<>0 OR (REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME=:incoming_lookup AND BINARY REFERENCED_TABLE_SCHEMA=BINARY DATABASE() AND BINARY REFERENCED_TABLE_NAME=:incoming_exact))';
 $candidate=['sql'=>'SELECT 1 FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_NAME IS NOT NULL AND '.$outgoing.' UNION ALL SELECT 1 FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_NAME IS NOT NULL AND '.$incoming.' LIMIT 1','parameters'=>$old['parameters']+['outgoing_lookup'=>'sosecurity_fk_probe','incoming_lookup'=>'sosecurity_fk_probe']];
 $constraints=['sql'=>'SELECT 1 FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE (LOWER(CONSTRAINT_SCHEMA)=LOWER(DATABASE()) AND LOWER(TABLE_NAME)=:outgoing AND (@@lower_case_table_names<>0 OR (BINARY CONSTRAINT_SCHEMA=BINARY DATABASE() AND BINARY TABLE_NAME=:outgoing_exact))) OR (LOWER(UNIQUE_CONSTRAINT_SCHEMA)=LOWER(DATABASE()) AND LOWER(REFERENCED_TABLE_NAME)=:incoming AND (@@lower_case_table_names<>0 OR (BINARY UNIQUE_CONSTRAINT_SCHEMA=BINARY DATABASE() AND BINARY REFERENCED_TABLE_NAME=:incoming_exact))) LIMIT 1','parameters'=>$old['parameters']];
 $legacyOutgoing=str_replace('TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:outgoing_lookup AND ','',$outgoing);$legacyIncoming=str_replace('REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME=:incoming_lookup AND ','',$incoming);$old['sql']='SELECT 1 FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_NAME IS NOT NULL AND (('.$legacyOutgoing.') OR ('.$legacyIncoming.')) LIMIT 1;';
 foreach(['none','incoming','disabled','cross-schema','outgoing','case-other'] as $mode){
  if($mode==='incoming'){$pdo->exec('CREATE TABLE fk_probe_child(id INT NOT NULL,FOREIGN KEY(id) REFERENCES sosecurity_fk_probe(id)) ENGINE=InnoDB');$created[]='fk_probe_child';}
  if($mode==='disabled'){$pdo->exec('SET FOREIGN_KEY_CHECKS=0');}
  if($mode==='cross-schema'){$pdo->exec('DROP TABLE fk_probe_child');array_pop($created);$pdo->exec('CREATE TABLE sosecurity_fk_other.fk_probe_child(id INT NOT NULL,FOREIGN KEY(id) REFERENCES sosecurity_test.sosecurity_fk_probe(id)) ENGINE=InnoDB');$created[]='sosecurity_fk_other.fk_probe_child';}
  if($mode==='outgoing'){$pdo->exec('DROP TABLE sosecurity_fk_other.fk_probe_child');array_pop($created);$pdo->exec('CREATE TABLE fk_probe_parent(id INT NOT NULL PRIMARY KEY) ENGINE=InnoDB');$created[]='fk_probe_parent';$pdo->exec('ALTER TABLE sosecurity_fk_probe ADD CONSTRAINT probe_outgoing FOREIGN KEY(id) REFERENCES fk_probe_parent(id)');}
  if($mode==='case-other'){if((int)$pdo->query('SELECT @@lower_case_table_names')->fetchColumn()!==0){echo 'NOT RUN distinct-case identifiers: server folds table names'.PHP_EOL;continue;}$pdo->exec('ALTER TABLE sosecurity_fk_probe DROP FOREIGN KEY probe_outgoing');$pdo->exec('CREATE TABLE SOSECURITY_FK_PROBE(id INT NOT NULL,FOREIGN KEY(id) REFERENCES fk_probe_parent(id)) ENGINE=InnoDB');$created[]='SOSECURITY_FK_PROBE';}
  $times=[];foreach(['original'=>$old,'candidate'=>$candidate,'constraints'=>$constraints,'deployed'=>SoSecurity\Support\SqlSchema::foreignKeyChecks('mysql','sosecurity_fk_probe')[0]] as $name=>$query){$at=microtime(true);for($i=0;$i<20;++$i){$q=$pdo->prepare($query['sql']);$q->execute($query['parameters']);Check::same(!in_array($mode,['none','case-other'],true),$q->fetchColumn()!==false);$q->closeCursor();}$times[$name]=microtime(true)-$at;$q=$reader->prepare($query['sql']);$q->execute($query['parameters']);Check::same(!in_array($mode,['none','case-other'],true),$q->fetchColumn()!==false);$q->closeCursor();}
  echo 'FOREIGN_PLAN '.json_encode(['mode'=>$mode,'iterations'=>20,'seconds'=>$times]).PHP_EOL;
 }
}finally{foreach(array_reverse($created) as $table){$pdo->exec('DROP TABLE '.$table);}$pdo->exec('SET FOREIGN_KEY_CHECKS=1');}
echo 'PASS equivalent foreign dependency probes '.Check::$assertions.PHP_EOL;
